      ro: "Un ora\\u0219 antic pe coasta mediteranean\\u0103, cu un teatru roman impresionant \\u0219i mozaicuri frumoase.",
      en: "An ancient city on the Mediterranean coast featuring an impressive Roman theater and beautiful mosaics.",
      es: "Una antigua ciudad en la costa mediterránea con un impresionante teatro romano y hermosos mosaicos.",
      pt: "Uma cidade antiga na costa mediterrânea com um impressionante teatro romano e belos mosaicos.",
