      hu: ["K\\u00fcr\\u00e9n\\u00e9 kik\\u00f6t\\u0151jek\\u00e9nt szolg\\u00e1lt.", "H\\u00e1rom biz\\u00e1nci bazilik\\u00e1ja van.", "A v\\u00e1ros egy r\\u00e9sze v\\u00edz alatt fekszik."],
      ro: ["A servit drept port pentru Cyrene.", "De\\u021bine trei bazilici bizantine.", "P\\u0103r\\u021bi ale ora\\u0219ului sunt sub ap\\u0103."],
      en: ["Served as the port of Cyrene.", "Has three Byzantine basilicas.", "Parts of the city are underwater."],
