      hu: ["Kr. e. 3. sz\\u00e1zadban alap\\u00edtott\\u00e1k.", "Itt tal\\u00e1lhat\\u00f3 az Oszlopok Palot\\u00e1ja.", "Egy ideig Kirenaika f\\u0151v\\u00e1rosa volt."],
      ro: ["Fondat \\u00een secolul al III-lea \\u00ee.Hr.", "G\\u0103zduie\\u0219te Palatul Coloanelor.", "A fost capitala Cirenaicii pentru o vreme."],
      en: ["Founded in the 3rd century BC.", "Features the Palace of the Columns.", "Was capital of Cyrenaica for a time."],
      es: ["Fundada en el siglo III a. C.", "Posee el Palacio de las Columnas.", "Fue durante un tiempo la capital de la Cirenaica."],
