      hu: ["Az \\u00f3korban alap\\u00edtott\\u00e1k.", "Oszm\\u00e1n \\u00e9p\\u00edt\\u00e9szeti hat\\u00e1sok \\u00e9rt\\u00e9k.", "A hagyom\\u00e1nyos k\\u00e9zm\\u0171vess\\u00e9g k\\u00f6zpontja."],
