      pt: "Uma mesquita belamente decorada no coração de Trípoli, famosa pelos seus azulejos e trabalhos em mármore.",
      fr: "Une mosquée magnifiquement décorée au cœur de Tripoli, célèbre pour ses carreaux et ses travaux de marbre.",
