      hu: ["A csata 1942. május 26-án kezdődött", "Marie-Pierre Kœnig tábornok vezette a védőket", "A Szabad Francia Erők 16 napig álltak ellen", "A németeket a híres 'Sivatagi Róka', Erwin Rommel vezette", "A védők éjszakai kitöréssel menekültek meg a gyűrűből", "A csata helyszíne ma fontos háborús emlékhely Líbiában"],
      ro: ["Bătălia a avut loc în perioada mai-iunie 1942", "Forțele franceze au fost conduse de generalul Marie-Pierre Kœnig", "Aproximativ 3.700 de soldați au apărat fortul izolat", "Atacul a fost coordonat de generalul german Erwin Rommel", "Rezistența a durat 16 zile sub un soare arzător", "Locul este marcat de un monument comemorativ oficial"],
      en: ["The battle took place from May 26 to June 11, 1942", "General Marie-Pierre Kœnig led the Free French Forces", "The garrison consisted of approximately 3,700 soldiers", "It delayed Erwin Rommel's advance toward the Suez Canal", "The French troops successfully broke out on June 11", "Remains of the defensive trenches are still visible today"],
      es: ["El lugar de una importante batalla de la Segunda Guerra Mundial, donde las fuerzas de la Francia Libre resistieron heroicamente.", "Se encuentra en el territorio del estado de Libia, en el norte de África.", "Desempeña un papel en la identidad local de la región.", "Conocida por su importancia paisajística o cultural."],
      pt: ["O local de uma importante batalha da Segunda Guerra Mundial, onde as forças francesas livres resistiram heroicamente.", "Situa-se no território do Estado da Líbia, no Norte de África.", "Desempenha um papel na identidade local da região.", "Conhecida pela sua importância paisagística ou cultural."],
      fr: ["Le site d'une bataille importante de la Seconde Guerre mondiale, où les troupes françaises libres ont résisté héroïquement.", "Situé sur le territoire de l'État de Libye, en Afrique du Nord.", "Joue un rôle dans l'identité locale de la région.", "Connue pour son importance paysagère ou culturelle."],
