    coords: [12.167, 32.043],
    name: {
      de: "Qasr Al-Haj",
      hu: "Qasr Al-Haj",
      ro: "Qasr Al-Haj",
      en: "Qasr Al-Haj"},
    image: "/poi-images/ly-qasr-al-haj-history-v2.webp",
    descriptionAdvanced: {
      de: "Qasr Al-Haj ist einer der spektakulärsten und am besten erhaltenen befestigten Getreidespeicher (Ghurfas) im Jebel Nafusa-Gebirge in Libyen. Die kreisförmige Struktur wurde vermutlich im 12. Jahrhundert von Abdallah Abu Jatla erbaut und diente dazu, die Ernten der lokalen Berberstämme sicher vor Plünderern und Witterungseinflüssen zu lagern. Das Bauwerk besteht aus Stein, Lehm und Gips und umfasst insgesamt 114 Kammern, was symbolisch der Anzahl der Suren im Koran entspricht. Jede Familie der Region besaß eine eigene Kammer, in der Getreide, Olivenöl und Feigen über Jahre hinweg konserviert werden konnten. Die Architektur ist einzigartig: Ein massives, schmuckloses Äußeres schützt einen weiten Innenhof, von dem aus die einzelnen Lagerräume über Treppen erreichbar sind. Qasr Al-Haj war nicht nur ein funktionales Lagerhaus, sondern auch ein sozialer Treffpunkt und ein Symbol für die Gemeinschaft und Vorsorge der Amazigh-Kultur. Heute gilt der Qasr als architektonisches Meisterwerk und ist ein wichtiges Ziel für Touristen, die die traditionelle Lebensweise in den libyschen Bergen verstehen wollen. Die zeitlose Schönheit der organischen Formen fügt sich perfekt in die trockene Hügellandschaft ein.",
      hu: "Kaszr al-Hadzs Líbia egyik legkülönlegesebb építészeti emléke, egy hatalmas, kör alaprajzú erődített magtár a Nafúsza-hegység lábánál. A 12. században épült monumentális építményt Abdallah Abu Dzsatla alapította, hogy biztonságos tárolóhelyet nyújtson a környékbeli berber (amazigh) törzsek terményeinek. Az épületben pontosan 114 tárolókamra található, ami az iszlám hagyomány szerint a Korán szúráinak számát jelképezi. A családok itt őrizték legfontosabb kincseiket: búzát, árpát, olívaolajat és szárított fügét, védve azokat a sivatagi rablóktól és az éhezéstől. Az erőd falai kőből, agyagból és gipszből készültek, vastagságuk pedig kiváló hőszigetelést biztosított a forró nyári hónapokban. A belső udvarról nyíló több emeletnyi kamrarendszer fa létrákon és lépcsőkön keresztül érhető el, lenyűgöző látványt nyújtva a látogatóknak. Kaszr al-Hadzs nemcsak raktárként, hanem a közösségi összefogás szimbólumaként is szolgált, ahol a törzsi viszályok idején is béke honolt. Ma a világörökség részrehajló várományosa, és az amazigh kultúra egyik legfontosabb fennmaradt emléke Észak-Afrikában.",
      ro: "Qasr Al-Haj este un depozit fortificat de cereale (ghurfa) de o frumusețe rară, situat la poalele munților Jebel Nafusa din Libia. Această structură circulară masivă a fost construită în secolul al XII-lea de către Abdallah Abu Jatla pentru a servi drept hambare colective pentru comunitățile berbere locale. Impresionantul edificiu conține 114 camere de depozitare, număr care corespunde simbolic numărului de sure din Coran, fiecare aparținând unei anumite familii. Zidurile exterioare sunt groase și lipsite de ferestre, oferind protecție maximă împotriva raidurilor și a condițiilor climatice extreme ale deșertului. Materialele folosite – piatră, argilă și ipsos – au permis conservarea alimentelor precum grâul, curmalele și uleiul de măsline pentru perioade lungi de timp. Accesul la camerele dispuse pe mai multe niveluri se face prin scări de piatră interioare care dau spre o curte centrală vastă. Qasr Al-Haj nu este doar un depozit, ci o mărturie a ingeniozității arhitecturale Amazigh și a spiritului lor de solidaritate. Astăzi, monumentul este vizitat pentru designul său organic unic, fiind considerat unul dintre cele mai importante obiective culturale din vestul Libiei.",
      en: "Qasr Al-Haj is a magnificent example of a fortified communal granary, known as a ghurfa, located at the base of the Jebel Nafusa mountains in Libya. Built in the 12th century by Abdallah Abu Jatla, this massive circular structure was designed to protect the harvest of local Berber (Amazigh) tribes from raids and harsh weather. The complex features exactly 114 individual storage chambers, a number chosen to symbolize the 114 suras of the Quran. Each chamber belonged to a local family, who used it to store essential supplies such as grain, olive oil, and dried figs. The architecture utilizes local stone, mud, and gypsum, creating thick walls that provide natural insulation against the intense desert heat. From the central courtyard, multiple levels of storage rooms are accessible via stone stairs and wooden ladders, creating a visually striking interior. Qasr Al-Haj served not only as a warehouse but also as a symbol of communal security and agricultural foresight. Today, it stands as a masterpiece of traditional North African architecture and remains a major cultural landmark for the Amazigh people.",
      es: "Qasr Al-Haj es un elemento notable de la geografía y cultura libias. Un enorme granero bereber fortificado y circular, utilizado para almacenar las cosechas de las familias nómadas. Probablemente construido en el siglo XII. Contiene 114 cámaras de almacenamiento. Una obra maestra de la arquitectura bereber. Este lugar tiene una importancia especial en la historia de Libia, desde los asentamientos fenicios y romanos como Leptis Magna hasta la época otomana y moderna. Como muchos lugares significativos de Libia, este sitio combina la herencia púnico-romana y bereber con influencias mediterráneas y saharianas. Así, este lugar contribuye al perfil polifacético de Libia, entre ruinas antiguas, oasis del desierto y la costa del Mediterráneo.",
      pt: "Qasr Al-Haj é um elemento notável da geografia e cultura líbias. Um enorme celeiro berbere fortificado e circular, utilizado para armazenar as colheitas de famílias nómadas. Provavelmente construído no século XII. Contém 114 câmaras de armazenamento. Uma obra-prima da arquitetura berbere. Este local tem uma importância especial na história da Líbia, desde os assentamentos fenícios e romanos como Leptis Magna até à época otomana e moderna. Como muitos locais significativos na Líbia, este sítio combina a herança púnico-romana e berbere com influências mediterrânicas e saarianas. Assim, este local contribui para o perfil multifacetado da Líbia, entre ruínas antigas, oásis do deserto e a costa do Mediterrâneo.",
      fr: "Qasr Al-Haj est un élément remarquable de la géographie et de la culture libyennes. Un immense grenier berbère fortifié et circulaire, servant à stocker les récoltes des familles nomades. Probablement construit au XIIe siècle. Contient 114 chambres de stockage. Un chef-d'œuvre de l'architecture berbère. Ce lieu revêt une importance particulière dans l'histoire de la Libye, des colonies phéniciennes et romaines comme Leptis Magna jusqu'aux époques ottomane et moderne. Comme de nombreux sites importants en Libye, ce lieu allie l'héritage punico-romain et berbère aux influences méditerranéennes et sahariennes. Ce site contribue ainsi au profil diversifié de la Libye, entre ruines antiques, oasis du désert et côte méditerranéenne.",
    },
